def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    count = sum(1 for value in values if value > 4000)
    return {
        "value": count,
        "trace": {
            "threshold": 4000,
            "qualifying_years": count,
            "output_meta": {"currency": None, "scale": None, "unit": "years"},
        },
    }
